INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (1, 'pre_post', 'general', 'ภาพรวม', 'สิทธิในสิ่งแวดล้อมที่ดีประกอบด้วยสิทธิ 2 ประเภท คือ สิทธิเชิงเนื้อหาและสิทธิเชิงกระบวนการ', 1, 'สิทธิในสิ่งแวดล้อมที่ดีแบ่งเป็นสิทธิทางสิ่งแวดล้อมเชิงเนื้อหา (คุณภาพสิ่งแวดล้อมที่ทุกคนพึงได้รับ) และเชิงกระบวนการ (ขั้นตอนที่ทำให้เข้าถึงสิทธิเชิงเนื้อหาได้)', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (2, 'pre_post', 'general', 'ภาพรวม', 'สิทธิทางสิ่งแวดล้อมเชิงเนื้อหามีองค์ประกอบทั้งหมด 4 ประการ', 0, 'สิทธิเชิงเนื้อหามี 6 ประการ ได้แก่ อากาศสะอาด ภูมิอากาศที่ปลอดภัย น้ำที่ปลอดภัยและเพียงพอ อาหารที่ดีต่อสุขภาพและผลิตอย่างยั่งยืน สภาพแวดล้อมที่ปราศจากสารพิษ และระบบนิเวศและความหลากหลายทางชีวภาพที่ดี', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (3, 'pre_post', 'general', 'ภาพรวม', 'สิทธิทางสิ่งแวดล้อมเชิงกระบวนการ ได้แก่ สิทธิเข้าถึงข้อมูลข่าวสาร สิทธิมีส่วนร่วมในการตัดสินใจ และสิทธิเข้าถึงความยุติธรรมด้านสิ่งแวดล้อม', 1, 'สิทธิเชิงกระบวนการมี 3 ประการนี้ ถือเป็นเสาหลักที่ช่วยให้ประชาชนเข้าถึงสิทธิเชิงเนื้อหาได้', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (4, 'pre_post', 'general', 'ภาพรวม', 'สิทธิเชิงเนื้อหาทั้ง 6 องค์ประกอบแยกขาดจากกัน การปกป้ององค์ประกอบหนึ่งไม่ส่งผลต่อองค์ประกอบอื่น', 0, 'สิทธิเชิงเนื้อหาทั้ง 6 องค์ประกอบเชื่อมโยงและพึ่งพากัน การปกป้ององค์ประกอบใดองค์ประกอบหนึ่งมักส่งผลดีต่อองค์ประกอบอื่นด้วย', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (5, 'pre_post', 'general', 'ภาพรวม', 'สิทธิเชิงกระบวนการเป็นเพียงเครื่องมือเพื่อไปสู่สิทธิเชิงเนื้อหา ไม่มีคุณค่าในตัวเอง', 0, 'สิทธิเชิงกระบวนการไม่ได้เป็นแค่เครื่องมือ แต่เป็นสิทธิที่มีคุณค่าในตัวเอง ตามหลักประชาธิปไตย ความโปร่งใส และภาระรับผิดชอบในการจัดการสิ่งแวดล้อม', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (6, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'คณะมนตรีสิทธิมนุษยชนแห่งสหประชาชาติ (UNHRC) รับรองมติว่าสิทธิในสิ่งแวดล้อมที่ดีคือสิทธิมนุษยชน เมื่อวันที่ 8 ตุลาคม 2564', 1, 'UNHRC รับรองมติครั้งประวัติศาสตร์เมื่อ 8 ต.ค. 2564 ว่าการมีสภาพแวดล้อมที่ปลอดภัย สะอาด มีสุขภาพดี และยั่งยืน คือสิทธิมนุษยชน', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (7, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'ที่ประชุมสมัชชาใหญ่แห่งสหประชาชาติ (UNGA) ประกาศว่าการเข้าถึงสิ่งแวดล้อมที่สะอาด ดีต่อสุขภาพ และยั่งยืนคือสิทธิมนุษยชน เมื่อปี 2565', 1, 'UNGA มีมติเมื่อ 28 ก.ค. 2565 และเรียกร้องให้รัฐต่าง ๆ ยกระดับความพยายามให้ประชาชนเข้าถึงสิ่งแวดล้อมที่ดี', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (8, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'ในการลงมติของสมัชชาใหญ่แห่งสหประชาชาติเรื่องสิทธิในสิ่งแวดล้อมที่ดี มีรัฐคัดค้าน 8 ประเทศ', 0, 'มี 161 รัฐลงมติเห็นชอบ ไม่มีรัฐใดคัดค้าน และมี 8 รัฐงดออกเสียง', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (9, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'ปัจจุบันสิทธิในสิ่งแวดล้อมที่ดีได้รับการรับรองทางกฎหมายในรัฐสมาชิกสหประชาชาติมากกว่าร้อยละ 80', 1, 'มีการรับรองใน 161 จาก 193 รัฐสมาชิก ผ่านรัฐธรรมนูญ กฎหมาย และสนธิสัญญาระดับภูมิภาค', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (10, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'รัฐส่วนใหญ่ที่ยังไม่รับรองสิทธิในสิ่งแวดล้อมที่ดีในกฎหมาย คือประเทศอุตสาหกรรมขนาดใหญ่ที่คัดค้านสิทธินี้', 0, 'รัฐส่วนใหญ่ที่ยังไม่รับรองคือรัฐกำลังพัฒนาที่เป็นเกาะขนาดเล็ก ซึ่งสนับสนุนมติของ UN อย่างแข็งขัน แต่มีข้อจำกัดด้านศักยภาพในการแก้ไขรัฐธรรมนูญและกฎหมาย', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (11, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'อนุสัญญายุโรปว่าด้วยสิทธิมนุษยชนรับรองสิทธิในสิ่งแวดล้อมที่ดีไว้โดยตรง', 0, 'อนุสัญญายุโรปว่าด้วยสิทธิมนุษยชนไม่มีสิทธิในสิ่งแวดล้อมที่ดี ศาลสิทธิมนุษยชนยุโรปจึงระบุหลายครั้งว่าอนุสัญญาไม่ได้คุ้มครองสิทธิในการอนุรักษ์ธรรมชาติ', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (12, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'ปฏิญญาสตอกโฮล์ม ค.ศ. 1972 เป็นปฏิญญาสากลว่าด้วยสิ่งแวดล้อมฉบับแรกที่กล่าวถึงสิทธิของมนุษย์ในสิ่งแวดล้อม', 1, 'ปฏิญญาสตอกโฮล์มกล่าวถึงความสำคัญของสิ่งแวดล้อมและสิทธิของมนุษย์ในสิ่งแวดล้อมเป็นครั้งแรก แม้ยังไม่รับรองสิทธิในสิ่งแวดล้อมไว้อย่างชัดเจน', 'รายงานวิจัย กสม. ความสัมพันธ์ระหว่างสิทธิมนุษยชนและสิ่งแวดล้อม', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (13, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'ปฏิญญาสตอกโฮล์มและปฏิญญาริโอเป็นตราสารที่มีผลผูกพันทางกฎหมายให้รัฐต้องปฏิบัติตาม', 0, 'ทั้งสองฉบับเป็นตราสารประเภท Soft Law ซึ่งไม่มีผลผูกพันทางกฎหมาย แต่มีอิทธิพลต่อพัฒนาการของสิทธิในสิ่งแวดล้อม', 'รายงานวิจัย กสม. ความสัมพันธ์ระหว่างสิทธิมนุษยชนและสิ่งแวดล้อม', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (14, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'ปฏิญญาริโอ (Principle 10) กล่าวถึงสิทธิเชิงกระบวนการ เช่น การเข้าถึงข้อมูล การมีส่วนร่วม และการเข้าถึงความยุติธรรม', 1, 'ปฏิญญาริโอกล่าวถึงสิทธิเชิงกระบวนการไว้อย่างชัดเจนใน Principle 10 และเป็นรากฐานของอนุสัญญา Aarhus ในเวลาต่อมา', 'รายงานวิจัย กสม. ความสัมพันธ์ระหว่างสิทธิมนุษยชนและสิ่งแวดล้อม', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (15, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'ปฏิญญาริโอรับรองสิทธิในสิ่งแวดล้อมเชิงเนื้อหาไว้โดยตรงอย่างชัดแจ้ง', 0, 'ปฏิญญาริโอยังไม่ได้รับรองสิทธิในสิ่งแวดล้อมไว้โดยตรง ประเด็นหลักคือแนวคิดการพัฒนาอย่างยั่งยืนและสิทธิเชิงกระบวนการ', 'รายงานวิจัย กสม. ความสัมพันธ์ระหว่างสิทธิมนุษยชนและสิ่งแวดล้อม', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (16, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'อนุสัญญา Aarhus ค.ศ. 1998 ของภูมิภาคยุโรป เน้นเรื่องการเข้าถึงข้อมูล การมีส่วนร่วม และการเข้าถึงความยุติธรรมในเรื่องสิ่งแวดล้อม', 1, 'อนุสัญญา Aarhus เป็นตราสารที่บัญญัติรับรองสิทธิเชิงกระบวนการทั้ง 3 ประการในเรื่องสิ่งแวดล้อม', 'รายงานวิจัย กสม. ความสัมพันธ์ระหว่างสิทธิมนุษยชนและสิ่งแวดล้อม', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (17, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'กฎบัตรแอฟริกันว่าด้วยสิทธิมนุษยชนและสิทธิของประชาชน ยอมรับว่าสิทธิในสิ่งแวดล้อมที่ดีเป็นสิทธิมนุษยชนในลักษณะสิทธิเชิงกลุ่มของประชาชน', 1, 'กฎบัตรแอฟริกันรับรองสิทธิในสิ่งแวดล้อมที่ดีที่น่าพอใจที่เอื้อต่อการพัฒนา โดยใช้ควบคู่กับสิทธิในการพัฒนา และถือเป็นสิทธิร่วมกันของประชาชน', 'รายงานวิจัย กสม. ความสัมพันธ์ระหว่างสิทธิมนุษยชนและสิ่งแวดล้อม', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (18, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'การใช้สิทธิมนุษยชนเดิมที่มีอยู่แล้วมาปรับใช้กับปัญหาสิ่งแวดล้อมเป็นรายกรณี มีข้อจำกัดเมื่อความเสียหายยังไม่กระทบต่อมนุษย์โดยตรง', 1, 'เพราะสิทธิมนุษยชนเป็นสิทธิของมนุษย์ ไม่ใช่สิทธิของธรรมชาติ ถ้าความเสียหายตกกับสิ่งแวดล้อมแต่ยังไม่กระทบมนุษย์โดยตรงก็นำกลไกนี้มาใช้ได้ยาก', 'รายงานวิจัย กสม. ความสัมพันธ์ระหว่างสิทธิมนุษยชนและสิ่งแวดล้อม', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (19, 'pre_post', 'international', 'กฎหมาย/มติระหว่างประเทศ', 'ศาลในลาตินอเมริกาบางประเทศตีความว่า สิทธิในสิ่งแวดล้อมที่ดีคุ้มครองสิ่งแวดล้อมที่มีระบบนิเวศสมบูรณ์ แม้จะไม่มีประโยชน์ต่อมนุษย์โดยตรง', 1, 'ศาลในโคลอมเบีย คอสตาริกา เอกวาดอร์ และเม็กซิโก ตีความแบบเน้นระบบนิเวศ (eco-centric) ตามแนวคำปรึกษาของศาลสิทธิมนุษยชนระหว่างทวีปอเมริกา', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (20, 'pre_post', 'principles', 'หลักการ', 'หลักการไม่ถดถอย (Non-regression) หมายถึง รัฐไม่สามารถลดมาตรฐานด้านสิ่งแวดล้อมหรือสิทธิมนุษยชนลงได้ หากไม่มีเหตุผลที่จำเป็นอย่างยิ่ง', 1, 'ถ้าจำเป็นต้องลดมาตรฐานจริง ต้องทำให้น้อยที่สุดและได้สัดส่วนกับวัตถุประสงค์ เช่น การที่เปรูลดมาตรฐานคุณภาพอากาศถูกระบุว่าเป็นปัญหา', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (21, 'pre_post', 'principles', 'หลักการ', 'ตามหลักความระมัดระวัง (Precautionary Principle) หากยังไม่มีความแน่นอนทางวิทยาศาสตร์ครบถ้วน รัฐควรชะลอมาตรการป้องกันไว้ก่อน', 0, 'กลับกัน หลักความระมัดระวังระบุว่า เมื่อมีภัยคุกคามร้ายแรงหรือเสียหายถาวร การขาดความแน่นอนทางวิทยาศาสตร์ต้องไม่ถูกใช้เป็นเหตุผลเลื่อนมาตรการป้องกัน', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (22, 'pre_post', 'principles', 'หลักการ', 'หลักผู้ก่อมลพิษเป็นผู้จ่าย (Polluter Pays Principle) คือ ผู้ที่สร้างมลพิษต้องรับผิดชอบค่าใช้จ่ายในการป้องกัน ควบคุม และแก้ไขปัญหามลพิษ', 1, 'หลักนี้สะท้อนอยู่ใน Principle 16 ของปฏิญญาริโอ ที่ว่าผู้ก่อมลพิษควรเป็นผู้แบกรับต้นทุนของมลพิษ', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (23, 'pre_post', 'principles', 'หลักการ', 'พื้นที่สังเวย (Sacrifice zones) คือพื้นที่ที่มีมลพิษหรือความเสื่อมโทรมรุนแรง เพราะให้ความสำคัญกับผลกำไรมากกว่าสิทธิมนุษยชนและสุขภาพ', 1, 'รัฐควรให้ความสำคัญกับการฟื้นฟู และการชดเชยให้ชุมชนที่อาศัยอยู่ในพื้นที่เหล่านี้เป็นลำดับแรก', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (24, 'pre_post', 'principles', 'หลักการ', 'รัฐควรกำหนดมาตรฐานมลพิษและสารพิษโดยอิงวิทยาศาสตร์ที่ดีที่สุด เช่น แนวทางคุณภาพอากาศและน้ำดื่มขององค์การอนามัยโลก', 1, 'เป็นหลักวิทยาศาสตร์ที่ดีที่สุดที่มีอยู่ (Best available science) ที่ควรใช้กำหนดการตอบสนองของรัฐต่อวิกฤตสิ่งแวดล้อม', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (25, 'pre_post', 'principles', 'หลักการ', 'กลุ่มเปราะบาง เช่น ผู้หญิง เด็ก ผู้สูงอายุ ชนพื้นเมือง และผู้พิการ มักได้รับผลกระทบจากความเสียหายทางสิ่งแวดล้อมมากกว่าคนทั่วไป', 1, 'หลักการไม่เลือกปฏิบัติและความเท่าเทียมกำหนดให้รัฐต้องไม่ทำให้ความอยุติธรรมทางสิ่งแวดล้อมรุนแรงขึ้น และต้องแก้ไขให้ดีขึ้น', 'Boyd, D. R. (2024). The Right to a Healthy Environment: A User''s Guide', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (26, 'pre_post', 'clean_air', 'อากาศสะอาด', 'องค์การอนามัยโลกระบุว่ามลพิษทางอากาศเป็นสาเหตุการเสียชีวิตก่อนวัยอันควรของประชากรโลกประมาณ 7 แสนคนต่อปี', 0, 'ตัวเลขที่ถูกต้องคือประมาณ 7 ล้านคนต่อปี', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (27, 'pre_post', 'clean_air', 'อากาศสะอาด', 'สหประชาชาติกำหนดให้วันที่ 7 กันยายนของทุกปีเป็นวันอากาศสะอาดสากล (International Day of Clean Air)', 1, 'เพื่อให้ทั่วโลกตระหนักถึงความสำคัญของอากาศบริสุทธิ์ต่อสุขภาพ การดำรงชีวิต เศรษฐกิจ และสิ่งแวดล้อม', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (28, 'pre_post', 'clean_air', 'อากาศสะอาด', 'ประเทศไทยมีกฎหมายที่คุ้มครองสิทธิในอากาศสะอาดโดยตรงแล้ว', 0, 'ข้อมูลของ กสม. ระบุว่าไทยยังไม่มีกฎหมายคุ้มครองสิทธิในอากาศสะอาดโดยตรง แต่มีความพยายามผลักดันร่าง พ.ร.บ. บริหารจัดการเพื่ออากาศสะอาด', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (29, 'pre_post', 'clean_air', 'อากาศสะอาด', 'มลพิษทางอากาศเกิดจากโรงงานอุตสาหกรรมเท่านั้น การใช้ถ่านหรือฟืนทำอาหารในครัวเรือนไม่ก่อมลพิษทางอากาศ', 0, 'แหล่งกำเนิดมีหลายแหล่ง ได้แก่ การคมนาคม การเกษตรและการเผา การทำเหมือง การผลิตไฟฟ้าและอุตสาหกรรม รวมถึงการใช้ถ่าน ฟืน หรือมูลสัตว์ในครัวเรือน', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (30, 'pre_post', 'climate', 'ภูมิอากาศ', 'ปี 2567 เป็นปีที่ร้อนที่สุดในประวัติศาสตร์ โดยอุณหภูมิเฉลี่ยของโลกสูงกว่ายุคก่อนอุตสาหกรรมมากกว่า 1.5 องศาเซลเซียส', 1, 'เทียบกับยุคก่อนอุตสาหกรรม (ช่วงปี 2393–2443)', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (31, 'pre_post', 'climate', 'ภูมิอากาศ', 'การที่ผู้คนต้องย้ายถิ่นฐานเพราะผลกระทบจากการเปลี่ยนแปลงสภาพภูมิอากาศ เช่น ระดับน้ำทะเลสูงขึ้น เรียกว่า Climate Migration', 1, 'ความร้อนทำให้น้ำแข็งขั้วโลกละลาย ระดับน้ำทะเลสูงขึ้น และคุกคามที่อยู่อาศัย จนเกิดผู้ลี้ภัยหรือผู้พลัดถิ่นจากสภาพภูมิอากาศ', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (32, 'pre_post', 'climate', 'ภูมิอากาศ', 'การเปลี่ยนแปลงสภาพภูมิอากาศไม่เกี่ยวข้องกับโรคที่มีแมลงเป็นพาหะ เช่น ไข้เลือดออกและไข้มาลาเรีย', 0, 'โลกร้อนทำให้โรคที่มีแมลงเป็นพาหะ เช่น ไข้เลือดออก มาลาเรีย และไข้ซิกา ขยายพื้นที่ไปสู่ภูมิภาคใหม่ ๆ มากขึ้น', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (33, 'pre_post', 'climate', 'ภูมิอากาศ', 'ผู้สูงอายุเป็นกลุ่มเปราะบางที่มีความเสี่ยงต่อโรคจากความร้อน เช่น โรคลมแดดและหัวใจวาย', 1, 'กลุ่มเปราะบางอื่น ๆ ได้แก่ เด็ก ผู้หญิง ผู้พิการ กลุ่มชาติพันธุ์ และคนจน', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (34, 'pre_post', 'water', 'น้ำ', 'สหประชาชาติรายงาน (2567) ว่ามีผู้คนทั่วโลกประมาณ 2 ร้อยล้านคนที่ไม่มีน้ำสะอาดใช้', 0, 'ตัวเลขที่ถูกต้องคือมากกว่า 2 พันล้านคน', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (35, 'pre_post', 'water', 'น้ำ', 'องค์ประกอบของสิทธิในน้ำ ได้แก่ เพียงพอ ปลอดภัย เข้าถึงได้ ราคาที่จ่ายไหว และไม่เลือกปฏิบัติ', 1, 'น้ำต้องมีพอใช้ ปราศจากสารพิษ อยู่ในระยะที่เข้าถึงได้สะดวก ค่าใช้จ่ายไม่เกินความสามารถ และทุกคนเข้าถึงได้อย่างเท่าเทียม', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (36, 'pre_post', 'water', 'น้ำ', 'สหประชาชาติ (2553) มีมติรับรองว่าสิทธิในการเข้าถึงน้ำดื่มและการอนามัยที่สะอาดปลอดภัยเป็นสิทธิมนุษยชน', 1, 'และเรียกร้องให้รัฐและองค์การระหว่างประเทศช่วยจัดหาน้ำดื่มและสุขาภิบาลที่สะอาดในราคาที่เป็นธรรมสำหรับทุกคน', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (37, 'pre_post', 'water', 'น้ำ', 'น้ำเป็นทรัพยากรธรรมชาติที่มีไม่จำกัด จึงไม่จำเป็นต้องจัดสรรอย่างเป็นธรรม', 0, 'น้ำเป็นทรัพยากรที่มีอยู่อย่างจำกัดและเป็นทรัพยากรสาธารณะ ไทยเองก็มีปัญหาการแย่งชิงน้ำระหว่างภาคอุตสาหกรรมกับภาคเกษตรกรรม', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (38, 'pre_post', 'food', 'อาหาร', 'อาหารที่ดีต่อสุขภาพและยั่งยืน หมายถึงอาหารที่มีปริมาณเพียงพอเท่านั้น ไม่เกี่ยวกับวิธีการผลิต', 0, 'อาหารที่ดีต้องปลอดภัย เพียงพอ มีโภชนาการดี ซื้อได้ในราคาที่เข้าถึง และผลิตอย่างยั่งยืนโดยไม่ทำลายสิ่งแวดล้อม', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (39, 'pre_post', 'food', 'อาหาร', 'สิทธิในอาหาร (Right to food) ได้รับการรับรองไว้ในกติการะหว่างประเทศว่าด้วยสิทธิทางเศรษฐกิจ สังคม และวัฒนธรรม (ICESCR)', 1, 'ICESCR ระบุว่าทุกคนมีสิทธิในมาตรฐานการครองชีพที่เพียงพอ ซึ่งรวมถึงอาหาร เสื้อผ้า และที่อยู่อาศัย', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (40, 'pre_post', 'food', 'อาหาร', 'มีประชากรกว่า 1 ใน 3 ของโลกหรือราว 2.8 พันล้านคน ที่ไม่สามารถจ่ายเงินเพื่อเข้าถึงอาหารที่ดีต่อสุขภาพได้', 1, 'สะท้อนว่าคนจำนวนมาก โดยเฉพาะคนยากจนและกลุ่มเปราะบาง ยังขาดแคลนอาหารที่มีคุณภาพในราคาที่เข้าถึงได้', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (41, 'pre_post', 'toxic', 'สารพิษ', 'การผลิตและใช้สารเคมีทั่วโลกเพิ่มขึ้นกว่า 3 เท่า นับตั้งแต่ปี 2543', 1, 'และมีผู้เสียชีวิตจากการสัมผัสสารเคมีอันตรายกว่า 1.6 ล้านคนต่อปี', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (42, 'pre_post', 'toxic', 'สารพิษ', 'เด็กเป็นกลุ่มที่เปราะบางที่สุดต่อสารพิษ การสัมผัสตะกั่วในวัยเด็กเชื่อมโยงกับ IQ ที่ต่ำลงและปัญหาพัฒนาการทางสมอง', 1, 'การได้รับสารปรอทขณะตั้งครรภ์ก็ส่งผลต่อพัฒนาการของทารกในครรภ์อย่างถาวร', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (43, 'pre_post', 'toxic', 'สารพิษ', 'ประเทศรายได้สูงได้รับผลกระทบจากสารเคมีอันตรายมากกว่าประเทศรายได้น้อย', 0, 'ประเทศรายได้น้อยได้รับผลกระทบมากกว่า เพราะสารเคมีอันตรายบางชนิดที่ถูกห้ามใช้ในประเทศพัฒนาแล้วยังถูกส่งออกไปใช้ในประเทศกำลังพัฒนา', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (44, 'pre_post', 'ecosystem', 'ระบบนิเวศ', 'การระบาดของปลาหมอคางดำเป็นตัวอย่างของการรุกรานของชนิดพันธุ์ต่างถิ่นที่ทำลายระบบนิเวศ', 1, 'สัตว์หรือพืชต่างถิ่นที่ถูกนำเข้ามาจะเบียดเบียนสิ่งมีชีวิตพื้นถิ่น และทำลายความหลากหลายทางชีวภาพ', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (45, 'pre_post', 'ecosystem', 'ระบบนิเวศ', 'การทำประมงเกินขนาด (Overfishing) ช่วยเพิ่มความหลากหลายทางชีวภาพในทะเล', 0, 'การทำประมงเกินอัตราที่ปลาจะเพิ่มประชากรมาแทนที่ได้ทัน ทำให้สัตว์น้ำบางชนิดใกล้สูญพันธุ์', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (46, 'pre_post', 'ecosystem', 'ระบบนิเวศ', 'แนวทางปกป้องระบบนิเวศอย่างหนึ่ง คือการเพิ่มพื้นที่อนุรักษ์ โดยให้ชุมชนท้องถิ่นและชนพื้นเมืองมีส่วนร่วมในการดูแล', 1, 'แนวทางอื่น ได้แก่ ยกระดับกฎหมาย ฟื้นฟูระบบนิเวศที่เสื่อมโทรม ส่งเสริมเศรษฐกิจที่เป็นมิตรต่อระบบนิเวศ และสร้างแรงจูงใจในการอนุรักษ์', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (47, 'pre_post', 'information', 'ข้อมูลข่าวสาร', 'หลัก "เปิดเผยเป็นหลัก ปกปิดเป็นข้อยกเว้น" เป็นหลักของ พ.ร.บ. ข้อมูลข่าวสารของราชการ พ.ศ. 2540', 1, 'ประชาชนต้องเข้าถึงข้อมูลข่าวสารที่หน่วยงานรัฐถือครองได้ ยกเว้นข้อมูลที่กฎหมายกำหนดให้ปกปิด', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (48, 'pre_post', 'participation', 'การมีส่วนร่วม', 'การมีส่วนร่วมของประชาชนควรเปิดให้เฉพาะหลังจากที่รัฐตัดสินใจเรื่องโครงการเสร็จแล้ว', 0, 'การมีส่วนร่วมต้องเปิดโอกาสให้ประชาชนที่เกี่ยวข้องร่วมตัดสินใจตั้งแต่เริ่มต้น และในทุกระดับของการจัดทำกฎหมาย นโยบาย แผนงาน หรือโครงการ', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (49, 'pre_post', 'justice', 'ความยุติธรรม', 'นักปกป้องสิทธิมนุษยชนด้านสิ่งแวดล้อมควรได้รับการคุ้มครองจากการถูกคุกคามและความรุนแรงทุกรูปแบบ', 1, 'เป็นส่วนหนึ่งของสิทธิในการเข้าถึงความยุติธรรมด้านสิ่งแวดล้อม เพราะนักปกป้องสิทธิหลายคนถูกข่มขู่ ดำเนินคดี หรือถูกทำร้ายจากการปกป้องชุมชนของตน', 'สื่อ กสม. ชวนศึกษาเรื่องสิทธิมนุษยชนสิ่งแวดล้อม (มิ.ย. 2568)', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO questions (id, bank, category, category_th, question, answer, explanation, source, is_active) VALUES (50, 'pre_post', 'justice', 'ความยุติธรรม', 'รัฐธรรมนูญไทย พ.ศ. 2517 และ พ.ศ. 2521 บัญญัติเรื่องสิ่งแวดล้อมไว้ในหมวดแนวนโยบายแห่งรัฐ จึงมีผลผูกพันให้รัฐต้องปฏิบัติอย่างเคร่งครัด', 0, 'การบัญญัติไว้ในหมวดแนวนโยบายแห่งรัฐไม่ก่อพันธะผูกพันให้รัฐต้องปฏิบัติตาม', 'รายงานวิจัย กสม. ความสัมพันธ์ระหว่างสิทธิมนุษยชนและสิ่งแวดล้อม', 1) ON DUPLICATE KEY UPDATE bank=VALUES(bank), category=VALUES(category), category_th=VALUES(category_th), question=VALUES(question), answer=VALUES(answer), explanation=VALUES(explanation), source=VALUES(source), is_active=VALUES(is_active);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-AIR-01', 'R-AIR-A', 'right', 'substantive', 'สิทธิในอากาศสะอาด', 'อากาศสะอาด', 'ลดมลพิษทางอากาศจากแหล่งกำเนิดต่างๆ เช่น ยานพาหนะ, โรงงาน, การเผาในที่โล่ง', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'อุณหภูมิโลกสูงขึ้นอย่างต่อเนื่อง, ค่าฝุ่น PM 2.5 เกินมาตรฐาน', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#DDF5F4') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-AIR-02', 'R-AIR-B', 'right', 'substantive', 'สิทธิในอากาศสะอาด', 'อากาศสะอาด', 'การกำหนดมาตรฐานคุณภาพอากาศที่เข้มงวดและแผนปฏิบัติการคุณภาพอากาศระดับชาติ การเปลี่ยนผ่านสู่พลังงานหมุนเวียน', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'อุณหภูมิโลกสูงขึ้นอย่างต่อเนื่อง, ค่าฝุ่น PM 2.5 เกินมาตรฐาน', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#DDF5F4') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-WAT-01', 'R-WAT-A', 'right', 'substantive', 'สิทธิในน้ำปลอดภัยและเพียงพอ', 'น้ำปลอดภัยเพียงพอ', 'เข้าถึงน้ำดื่มที่ปลอดภัยและสุขาภิบาล การจัดการทรัพยากรน้ำแบบบูรณาการและการจัดสรรน้ำอย่างเป็นธรรม', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'อุณหภูมิโลกสูงขึ้นอย่างต่อเนื่อง, การทำเหมืองแร่ในพื้นที่ต้นน้ำ', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#5DA9D6') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-WAT-02', 'R-WAT-B', 'right', 'substantive', 'สิทธิในน้ำปลอดภัยและเพียงพอ', 'น้ำปลอดภัยเพียงพอ', 'การบำบัดน้ำเสียก่อนปล่อยสู่สิ่งแวดล้อม การปกป้องระบบนิเวศทางน้ำ', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'อุณหภูมิโลกสูงขึ้นอย่างต่อเนื่อง, การทำเหมืองแร่ในพื้นที่ต้นน้ำ', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#5DA9D6') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-FOD-01', 'R-FOD-A', 'right', 'substantive', 'สิทธิในอาหารที่ดีและผลิตอย่างยั่งยืน', 'อาหารยั่งยืน', 'ปฏิรูประบบอาหารให้ยั่งยืน ลดผลกระทบต่อสิ่งแวดล้อม เช่น ลดการปล่อยก๊าซเรือนกระจก, ลดการใช้น้ำและสารเคมี, ฟื้นฟูสุขภาพดิน', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'อุณหภูมิโลกสูงขึ้นอย่างต่อเนื่อง, การระบาดของปลาหมอคางดำ, ปลูกพืชเชิงเดี่ยวในระบบเกษตรพันธสัญญา', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#FFD36B') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-FOD-02', 'R-FOD-B', 'right', 'substantive', 'สิทธิในอาหารที่ดีและผลิตอย่างยั่งยืน', 'อาหารยั่งยืน', 'ส่งเสริมแนวทางเกษตรกรรมเชิงนิเวศ (agroecology) และเกษตรอินทรีย์ ลดการสูญเสียอาหารและขยะอาหาร', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'อุณหภูมิโลกสูงขึ้นอย่างต่อเนื่อง, การระบาดของปลาหมอคางดำ, ปลูกพืชเชิงเดี่ยวในระบบเกษตรพันธสัญญา', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#FFD36B') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-CLM-01', 'R-CLM-A', 'right', 'substantive', 'สิทธิในสภาพภูมิอากาศที่ปลอดภัย', 'ภูมิอากาศปลอดภัย', 'ลดการปล่อยก๊าซเรือนกระจกอย่างเร่งด่วน โดยเฉพาะการยุติการใช้เชื้อเพลิงฟอสซิล (ก๊าซธรรมชาติ, น้ำมัน, ถ่านหิน)', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'อุณหภูมิโลกสูงขึ้นอย่างต่อเนื่อง, การตัดไม้ทำลายป่า', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#DCEB77') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-CLM-02', 'R-CLM-B', 'right', 'substantive', 'สิทธิในสภาพภูมิอากาศที่ปลอดภัย', 'ภูมิอากาศปลอดภัย', 'การส่งเสริมการเปลี่ยนผ่านพลังงานหมุนเวียนที่สะอาดและเป็นธรรม', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'อุณหภูมิโลกสูงขึ้นอย่างต่อเนื่อง, การตัดไม้ทำลายป่า', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#DCEB77') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-ECO-01', 'R-ECO-A', 'right', 'substantive', 'สิทธิในระบบนิเวศและความหลากหลายทางชีวภาพที่ดี', 'นิเวศหลากหลาย', 'อนุรักษ์ ฟื้นฟู และบริหารจัดการระบบนิเวศและความหลากหลายทางชีวภาพ การกำหนดพื้นที่คุ้มครอง', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'น้ำมันรั่วไหลในทะเล, การระบาดของปลาหมอคางดำ, การตัดไม้ทำลายป่า, ปลูกพืชเชิงเดี่ยวในระบบเกษตรพันธสัญญา', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#CF93E0') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-ECO-02', 'R-ECO-B', 'right', 'substantive', 'สิทธิในระบบนิเวศและความหลากหลายทางชีวภาพที่ดี', 'นิเวศหลากหลาย', 'การยุติเงินอุดหนุนที่ทำลายธรรมชาติ การป้องกันการแพร่กระจายของชนิดพันธุ์ต่างถิ่นที่รุกราน', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'น้ำมันรั่วไหลในทะเล, การระบาดของปลาหมอคางดำ, การตัดไม้ทำลายป่า, ปลูกพืชเชิงเดี่ยวในระบบเกษตรพันธสัญญา', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#CF93E0') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-TOX-01', 'R-TOX-A', 'right', 'substantive', 'สิทธิในสภาพแวดล้อมที่ปราศจากสารพิษ', 'ปลอดสารพิษ', 'ห้ามหรือเลิกใช้สารพิษอันตราย เช่น แร่ใยหิน, ยาฆ่าแมลงอันตรายสูง การป้องกันการสัมผัสสารพิษ', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'น้ำมันรั่วไหลในทะเล, การทำเหมืองแร่ในพื้นที่ต้นน้ำ, ปลูกพืชเชิงเดี่ยวในระบบเกษตรพันธสัญญา', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#BA8768') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-TOX-02', 'R-TOX-B', 'right', 'substantive', 'สิทธิในสภาพแวดล้อมที่ปราศจากสารพิษ', 'ปลอดสารพิษ', 'การฟื้นฟูพื้นที่ปนเปื้อน (sacrifice zones) การควบคุมสารเคมีและของเสีย', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมหมายเลข 1, 2 และ 3 อย่างละ 1 ใบ', 2, 'ป้องกันภัยคุกคามที่ตรงเงื่อนไข; ป้องกันสำเร็จครบ 2 ครั้ง ได้โบนัส +1 คะแนน', 'น้ำมันรั่วไหลในทะเล, การทำเหมืองแร่ในพื้นที่ต้นน้ำ, ปลูกพืชเชิงเดี่ยวในระบบเกษตรพันธสัญญา', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#BA8768') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
INSERT INTO cards (code, design_code, type, subtype, name, short_name, body_text, number, number_meaning, symbol, build_condition, points, ability, protects_or_protected_by, discard_count, deck_phase, color_hex) VALUES ('R-INF-01', 'R-INF-A', 'right', 'procedural', 'สิทธิในการเข้าถึงข้อมูลข่าวสาร', 'เข้าถึงข้อมูล', 'ให้ข้อมูลสิ่งแวดล้อมและผลกระทบที่เกี่ยวข้องเปิดเผยและเข้าถึงได้โดยสาธารณะ', NULL, NULL, NULL, 'ทิ้งการ์ดกิจกรรมสัญลักษณ์ "เข้าถึงข้อมูลข่าวสาร" 3 ใบ', 3, 'ช่วยเตรียมตัว: ก่อนหยิบการ์ดจากกองกลาง ดูการ์ดบนสุดของกองจั่ว แล้วเลือกวางไว้ที่เดิมหรือใต้กอง', 'โดนฟ้องปิดปาก (SLAPP)', NULL, 'ช่วงที่ 1 หรือ 2 (สุ่มแบ่ง 9/9)', '#CDCEC8') ON DUPLICATE KEY UPDATE design_code=VALUES(design_code), type=VALUES(type), subtype=VALUES(subtype), name=VALUES(name), short_name=VALUES(short_name), body_text=VALUES(body_text), number=VALUES(number), number_meaning=VALUES(number_meaning), symbol=VALUES(symbol), build_condition=VALUES(build_condition), points=VALUES(points), ability=VALUES(ability), protects_or_protected_by=VALUES(protects_or_protected_by), discard_count=VALUES(discard_count), deck_phase=VALUES(deck_phase), color_hex=VALUES(color_hex);
